"""Build evidence-labelled engine and case applicability records."""
import collections,json
from pathlib import Path
H=Path(__file__).resolve().parent;B=H.parent
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
write=lambda name,x:(B/name).write_text(json.dumps(x,indent=2,ensure_ascii=False),encoding='utf8')
sources=[
dict(id='opsin',url='https://github.com/dan2097/opsin',type='official source and public interface documentation',details='2.9.0 latest listed release, MIT; local experiments use different unpinned 3.0-SNAPSHOT'),
dict(id='opsin_release',url='https://github.com/dan2097/opsin/releases',type='official release notes',details='v2.9.0 notes primed number-letter locants and CLI warnings'),
dict(id='iupac_indicated_h',url='https://iupac.qmul.ac.uk/BlueBook/P1.html',type='authoritative nomenclature reference',details='P-14.7 distinguishes indicated and added indicated H'),
dict(id='iupac_tautomer',url='https://goldbook.iupac.org/terms/view/T06252',type='authoritative nomenclature reference',details='tautomerism'),
dict(id='acd',url='https://www.acdlabs.com/products/name/',type='official product documentation',details='ACD/Name, Name to Structure Batch, UI rule and atom numbering features'),
dict(id='acd_version',url='https://www.acdlabs.com/technical-support/current-software-versions/name/',type='official product version',details='Name 2025 page; do not infer local availability'),
dict(id='chemaxon_api',url='https://docs.chemaxon.com/lts-platinum/name-to-structure_developer-guide.html',type='official developer documentation',details='MolImporter.importMol API, name options and plugins'),
dict(id='chemaxon_license',url='https://docs.chemaxon.com/latest/jchem-microservices_licenses.html',type='official licensing documentation',details='separate name conversion license in microservices'),
dict(id='openeye_parse',url='https://docs.eyesopen.com/toolkits/python/lexichemtk/OEIUPACFunctions/OEParseIUPACName.html',type='official API documentation',details='OEParseIUPACName returns bool; failure can leave partial molecule'),
dict(id='openeye_locant',url='https://docs.eyesopen.com/toolkits/python/lexichemtk/OEIUPACFunctions/OENameLocant.html',type='official API documentation',details='OEParseIUPACName atom integer type has a locant index; OENameLocant renders it'),
dict(id='openeye_license',url='https://docs.eyesopen.com/toolkits/python/quickstart-python/license.html',type='official licensing documentation',details='toolkit license required'),
dict(id='rdkit_cx',url='https://github.com/rdkit/rdkit/blob/master/Docs/Book/RDKit_Book.rst',type='official RDKit documentation',details='CXSMILES parsing differs from strict plain SMILES; do not pass extended string to strict input gate'),
]
write('nomenclature_engine_sources.json',sources)
L='DEMONSTRATED_LOCALLY';D='DOCUMENTED_PROGRAMMATIC_CAPABILITY';S='VERIFIED_IN_SOURCE_CODE';G='DOCUMENTED_GUI_ONLY';V='VENDOR_CLAIM_ONLY';N='NOT_ESTABLISHED'
capabilities=['name_to_structure','parsed_nomenclature','descriptor_ownership','locant_to_atom','source_span','source_specificity','tautomer_representation','charge_protonation','components_stoichiometry','warnings','programmatic_access']
opsin=[(L,'26 public local name probes'),(S,'internal parser tree exists; no stable public provenance tree established'),(S,'private stereo application trace previously demonstrated only selected examples; no source spans or clone lineage'),(L,'CML and CX atom values, repeated and generated locants lack source ownership'),(N,'raw offsets not exposed in prior traces'),(N,'output does not certify explicit versus default choices'),(L,'pyridone/pyridinol FixedH differs, StdInChI equal; no source provenance'),(L,'candidate ionic graph observed, not source charge assignment'),(L,'components output, not complete component source trace'),(L,'public warning and ambiguity APIs observed; false is not proof unambiguous'),(L,'Java API and CLI; private hooks need instrumentation')]
acd=[(V,'name-to-structure product claim; locally unavailable'),(N,'name-to-structure parse tree not established'),(N,'structure-to-name GUI highlighting is not input ownership'),(G,'GUI generated numbering; input-name mapping not established'),(N,'no name input span API identified'),(N,'no explicit/default metadata identified'),(V,'vendor claims names and structures support; no local verification'),(N,'source-to-atom ionic semantics not established'),(N,'source component and stoichiometry trace not established'),(V,'vendor says ambiguous names may warn or offer alternatives; programmatic details unknown'),(D,'batch Windows/Linux documented; name-input semantic API not established')]
chemaxon=[(D,'MolImporter.importMol(name,"name") developer guide'),(N,'public grammar/parse tree not established'),(N,'input descriptor ownership not established'),(N,'GUI IUPAC numbering is not evidence of mapping original name'),(N,'source-span provenance not established'),(N,'input-default metadata not established'),(N,'source-level tautomer preservation not established'),(N,'source ionic atom mapping not established'),(N,'component provenance not established'),(N,'API warning/completeness semantics not established'),(D,'Java API and CLI/microservices; naming license required')]
openeye=[(D,'OEParseIUPACName; boolean failure may yield partial molecule'),(N,'public parse tree not established'),(N,'locant field does not itself establish descriptor or fragment ownership'),(D,'OENameLocant / GetIntType document locant index on parsed atoms; source occurrence correspondence unestablished'),(N,'input character spans not established'),(N,'defaults vs explicit token metadata not established'),(N,'named tautomer provenance not established'),(N,'name-to-ionic-site trace not established'),(N,'component/stoichiometry source trace not established'),(N,'documented parse return boolean; complete ambiguity and warning behavior not established'),(D,'Python/Java/C++ SDK; license required')]
matrix=[]
for name,items in [('OPSIN',opsin),('ACD/Labs Name',acd),('ChemAxon Name to Structure',chemaxon),('OpenEye Lexichem',openeye)]:
    matrix.append(dict(engine=name,local_availability='available for OPSIN' if name=='OPSIN' else 'not established; no executable or Python module found in bounded check',capabilities={c:dict(evidence=e,detail=d) for c,(e,d) in zip(capabilities,items)}))
write('engine_capability_matrix.json',matrix)
taxonomy=read(B/'NOMENCLATURE_FALSE_HOLD_TAXONOMY.json');probes=read(B/'engine_probe_results.json')
observed={x.get('record_id'):x for x in probes['cases'] if x.get('record_id') is not None};cases=[]
for x in taxonomy:
    p=x['suspected_nomenclature_patterns'];i=x['record_id'];primary=x['primary_blocker']
    if primary=='tautomer specificity':category='POTENTIALLY_ADDRESSABLE_BUT_FURTHER_WORK_REQUIRED';why='A name-to-atom source constraint might help; complete mobile-site mapping and claim scope not demonstrated.'
    elif primary=='charge/protonation' and 'nitro_group_may_explain_internal_formal_charges' in p:category='POTENTIALLY_ADDRESSABLE_BUT_FURTHER_WORK_REQUIRED';why='A mapped nitro-group interpretation may explain internal formal charges; all other source charge sites still need independent support.'
    else:category='INSUFFICIENT_EVIDENCE';why='Parsed graph differences or formal charge do not establish exact source claim scope or resolve every blocker.'
    cases.append(dict(record_id=i,preferred_name=x['preferred_name'],blocker=primary,classification=category,reason=why,locally_probed=i in observed,feature_present_is_not_case_mapping=True,all_identity_dimensions_validated=False,eligibility_recovered=False))
write('false_hold_engine_applicability.json',dict(cases=cases,classification_counts=dict(collections.Counter(x['classification'] for x in cases)),observed_full_eligibility_recoveries=0,conclusion='No representative output establishes local EXACT eligibility for the case or its cluster.'))
write('recommended_mapping_poc.json',dict(recommendation='INSTRUMENTED_OPSIN_POC_REQUIRED',scope='A narrow isolated source-H/functional-group ownership trace with pinned exact source; compare selected and rejected parses without production integration.',supplied_capability='Test whether grammar node, source span/clone lineage, owner fragment, and same-result CML atom can be linked reliably for a bounded class.',existing_work='Reuse prior isolated R/S trace; do not repeat it as a new finding.',blockers=['tautomer specificity','selected charge/protonation contexts','alias claim specificity as a separate downstream task'],criteria_accept=['pin matching source revision and artifact provenance','prove source span -> selected parse node -> fragment -> atom with clone/transform lineage','validate symmetry and ambiguity with explicit abstention','match independent positive, negative, underspecified and conflicting source constraints','preserve warnings and reject trace when provenance is incomplete'],criteria_reject=['fallback ordering or default silently presented as explicit','missing original-token lineage or graph correspondence','scope collision accepted','any historical unsafe source elevated to exact','any production or gate change'],limits='No expectation that this covers all nomenclature classes; FixedH and parser consensus cannot prove source semantics.',commercial_next='If an existing license is later available, run same blind challenge against OpenEye atom locant fields; ask vendor about source occurrence and ownership.'))
print(json.dumps({'taxonomy_count':len(cases),'applicability':dict(collections.Counter(x['classification'] for x in cases))},indent=2))
